using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

namespace G3.Formats.Trees
{
    /// <summary>
    /// A SpeedTree mesh as generated by the original SpeedTreeRT 4.0 (Tools/SptBake) for one .spt: branches, fronds and
    /// leaf cards for every discrete LOD, the 360° billboard and the collision primitives. Positions are engine
    /// units (cm) in Gothic 3 axes (Y up, left-handed), i.e. the tree at entity scale 1. Format: Docs/formats-speedtree.md §8.
    /// Generated from the user's installed game; never committed.
    /// </summary>
    public sealed class BakedTree
    {
        public const string Magic = "G3TREE";
        public const int Version = 1;

        public string Name;
        public float[] BoundsMin = new float[3], BoundsMax = new float[3];
        /// <summary>LOD distances as the engine uses them: .spt LodNear/LodFar × tree height in metres (cm).</summary>
        public float LodNear, LodFar;
        /// <summary>Raw .spt LOD values (before the height scaling).</summary>
        public float SptLodNear, SptLodFar;
        public readonly List<BakedMeshLod> Branches = new List<BakedMeshLod>();
        public readonly List<BakedMeshLod> Fronds = new List<BakedMeshLod>();
        public readonly List<BakedLeafLod> Leaves = new List<BakedLeafLod>();
        public BakedBillboard Billboard;
        public readonly List<BakedCollision> Collision = new List<BakedCollision>();

        public float Height => BoundsMax[1] - BoundsMin[1];
    }

    /// <summary>One discrete LOD of branch or frond geometry (indexed triangle list, front faces clockwise like Unity).</summary>
    public sealed class BakedMeshLod
    {
        public int Lod;
        /// <summary>Alpha-test reference 0..255 (SpeedTree uses 84 by default).</summary>
        public float AlphaTest;
        public float[] Positions, Normals, Tangents, Binormals;   // 3 per vertex
        public float[] Uv;                                        // 2 per vertex, v up
        public float[] WindWeight;                                // 1 per vertex, 0 = rigid
        public byte[] WindMatrix;                                 // 1 per vertex, 0..3
        public int[] Triangles;

        public int VertexCount => Positions?.Length / 3 ?? 0;
    }

    /// <summary>One discrete LOD of leaf cards. Cards face the camera; corners are in card space (x right, y up, cm).</summary>
    public sealed class BakedLeafLod
    {
        public int Lod;
        public float AlphaTest;
        public float[] Centers, Normals, Tangents, Binormals;     // 3 per leaf
        public uint[] Colors;                                     // ARGB per leaf (SpeedTree leaf dimming / colour variance)
        public float[] WindWeight;                                // 1 per leaf
        public byte[] WindMatrix;                                 // 1 per leaf, 0..3
        public byte[] MapIndex;                                   // leaf map variant
        public byte[] Cluster;                                    // billboard-table cluster; rock group = Cluster & 3
        public float[] Uv;                                        // 8 per leaf: 4 corners × (u, v up)
        public float[] Corners;                                   // 8 per leaf: 4 corners × (x, y) relative to the centre

        public int Count => Centers?.Length / 3 ?? 0;
    }

    /// <summary>The 360° billboard (far LOD): an upright quad around the tree axis, one atlas image per view angle.</summary>
    public sealed class BakedBillboard
    {
        public float AlphaTest;
        public float HalfWidth, Bottom, Top;                      // cm
        /// <summary>8 floats per image (4 corners × (u, v up)); corner order: top-right, top-left, bottom-left, bottom-right.</summary>
        public float[] ImageUvs;
        public int ImageCount => ImageUvs?.Length / 8 ?? 0;
    }

    /// <summary>Collision primitive exactly as the engine reads it (eCWraper_SpeedTreeRT::CreateCollisionShape).</summary>
    public sealed class BakedCollision
    {
        public const int Sphere = 0, Capsule = 1, Box = 2;
        public int Type;
        public float[] Position = new float[3];   // cm; capsule: bottom centre
        public float[] Dimensions = new float[3]; // sphere: r; capsule: r, total height, (r2); box: extents
    }

    /// <summary>Binary reader/writer for <see cref="BakedTree"/> (.g3tree, little-endian).</summary>
    public static class BakedTreeIO
    {
        public static void Write(BakedTree t, Stream s)
        {
            using var w = new BinaryWriter(s, Encoding.UTF8, true);
            w.Write(Encoding.ASCII.GetBytes(BakedTree.Magic));
            w.Write((ushort)BakedTree.Version);
            w.Write(t.Name ?? "");
            Floats(w, t.BoundsMin, 3); Floats(w, t.BoundsMax, 3);
            w.Write(t.LodNear); w.Write(t.LodFar); w.Write(t.SptLodNear); w.Write(t.SptLodFar);
            foreach (var list in new[] { t.Branches, t.Fronds })
            {
                w.Write(list.Count);
                foreach (var m in list)
                {
                    w.Write(m.Lod); w.Write(m.AlphaTest); w.Write(m.VertexCount);
                    Floats(w, m.Positions); Floats(w, m.Normals); Floats(w, m.Tangents); Floats(w, m.Binormals);
                    Floats(w, m.Uv); Floats(w, m.WindWeight); w.Write(m.WindMatrix);
                    w.Write(m.Triangles.Length);
                    foreach (var i in m.Triangles) w.Write(i);
                }
            }
            w.Write(t.Leaves.Count);
            foreach (var l in t.Leaves)
            {
                w.Write(l.Lod); w.Write(l.AlphaTest); w.Write(l.Count);
                Floats(w, l.Centers); Floats(w, l.Normals); Floats(w, l.Tangents); Floats(w, l.Binormals);
                foreach (var c in l.Colors) w.Write(c);
                Floats(w, l.WindWeight); w.Write(l.WindMatrix); w.Write(l.MapIndex); w.Write(l.Cluster);
                Floats(w, l.Uv); Floats(w, l.Corners);
            }
            w.Write(t.Billboard != null);
            if (t.Billboard != null)
            {
                var b = t.Billboard;
                w.Write(b.AlphaTest); w.Write(b.HalfWidth); w.Write(b.Bottom); w.Write(b.Top);
                w.Write(b.ImageCount); Floats(w, b.ImageUvs);
            }
            w.Write(t.Collision.Count);
            foreach (var c in t.Collision) { w.Write(c.Type); Floats(w, c.Position, 3); Floats(w, c.Dimensions, 3); }
        }

        public static BakedTree Read(Stream s)
        {
            using var r = new BinaryReader(s, Encoding.UTF8, true);
            if (Encoding.ASCII.GetString(r.ReadBytes(6)) != BakedTree.Magic) throw new InvalidDataException("not a .g3tree file");
            int version = r.ReadUInt16();
            if (version != BakedTree.Version) throw new InvalidDataException($".g3tree version {version}, expected {BakedTree.Version}");
            var t = new BakedTree { Name = r.ReadString() };
            t.BoundsMin = Floats(r, 3); t.BoundsMax = Floats(r, 3);
            t.LodNear = r.ReadSingle(); t.LodFar = r.ReadSingle(); t.SptLodNear = r.ReadSingle(); t.SptLodFar = r.ReadSingle();
            foreach (var list in new[] { t.Branches, t.Fronds })
            {
                int n = r.ReadInt32();
                for (int k = 0; k < n; k++)
                {
                    var m = new BakedMeshLod { Lod = r.ReadInt32(), AlphaTest = r.ReadSingle() };
                    int v = r.ReadInt32();
                    m.Positions = Floats(r, 3 * v); m.Normals = Floats(r, 3 * v); m.Tangents = Floats(r, 3 * v); m.Binormals = Floats(r, 3 * v);
                    m.Uv = Floats(r, 2 * v); m.WindWeight = Floats(r, v); m.WindMatrix = r.ReadBytes(v);
                    m.Triangles = new int[r.ReadInt32()];
                    for (int i = 0; i < m.Triangles.Length; i++) m.Triangles[i] = r.ReadInt32();
                    list.Add(m);
                }
            }
            int nl = r.ReadInt32();
            for (int k = 0; k < nl; k++)
            {
                var l = new BakedLeafLod { Lod = r.ReadInt32(), AlphaTest = r.ReadSingle() };
                int n = r.ReadInt32();
                l.Centers = Floats(r, 3 * n); l.Normals = Floats(r, 3 * n); l.Tangents = Floats(r, 3 * n); l.Binormals = Floats(r, 3 * n);
                l.Colors = new uint[n];
                for (int i = 0; i < n; i++) l.Colors[i] = r.ReadUInt32();
                l.WindWeight = Floats(r, n); l.WindMatrix = r.ReadBytes(n); l.MapIndex = r.ReadBytes(n); l.Cluster = r.ReadBytes(n);
                l.Uv = Floats(r, 8 * n); l.Corners = Floats(r, 8 * n);
                t.Leaves.Add(l);
            }
            if (r.ReadBoolean())
            {
                var b = new BakedBillboard { AlphaTest = r.ReadSingle(), HalfWidth = r.ReadSingle(), Bottom = r.ReadSingle(), Top = r.ReadSingle() };
                b.ImageUvs = Floats(r, 8 * r.ReadInt32());
                t.Billboard = b;
            }
            int nc = r.ReadInt32();
            for (int k = 0; k < nc; k++)
                t.Collision.Add(new BakedCollision { Type = r.ReadInt32(), Position = Floats(r, 3), Dimensions = Floats(r, 3) });
            return t;
        }

        public static BakedTree Read(string path)
        {
            using var f = File.OpenRead(path);
            return Read(f);
        }

        static void Floats(BinaryWriter w, float[] a, int expected = -1)
        {
            if (expected >= 0 && (a == null || a.Length != expected)) throw new ArgumentException("array length");
            foreach (var f in a) w.Write(f);
        }

        static float[] Floats(BinaryReader r, int n)
        {
            var bytes = r.ReadBytes(4 * n);
            if (bytes.Length != 4 * n) throw new EndOfStreamException();
            var a = new float[n];
            Buffer.BlockCopy(bytes, 0, a, 0, bytes.Length);
            return a;
        }
    }
}
